import{_ as t,o as n,c as a,aj as o}from"./chunks/framework.C6uXqnaX.js";const p=JSON.parse('{"title":"Adding harness support for additional testing environments","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"guide/testing/component-harnesses-testing-environments.md","filePath":"guide/testing/component-harnesses-testing-environments.md"}'),s={name:"guide/testing/component-harnesses-testing-environments.md"};function r(i,e,d,l,c,h){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="adding-harness-support-for-additional-testing-environments" tabindex="-1">Adding harness support for additional testing environments <a class="header-anchor" href="#adding-harness-support-for-additional-testing-environments" aria-label="Permalink to &quot;Adding harness support for additional testing environments&quot;">​</a></h1><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This guide assumes you&#39;ve already read the <a href="/guide/testing/component-harnesses-overview">component harnesses overview guide</a>. Read that first if you&#39;re new to using component harnesses.</p></div><h3 id="when-does-adding-support-for-a-test-environment-make-sense" tabindex="-1">When does adding support for a test environment make sense? <a class="header-anchor" href="#when-does-adding-support-for-a-test-environment-make-sense" aria-label="Permalink to &quot;When does adding support for a test environment make sense?&quot;">​</a></h3><p>To use component harnesses in the following environments, you can use Angular CDK&#39;s two built-in environments:</p><ul><li>Unit tests</li><li>WebDriver end-to-end tests</li></ul><p>To use a supported testing environment, read the <a href="/guide/testing/creating-component-harnesses">Creating harnesses for your components guide</a>.</p><p>Otherwise, to add support for other environments, you need to define how to interact with a DOM element and how DOM interactions work in your environment. Continue reading to learn more.</p><h3 id="cdk-installation" tabindex="-1">CDK Installation <a class="header-anchor" href="#cdk-installation" aria-label="Permalink to &quot;CDK Installation&quot;">​</a></h3><p>The <a href="https://material.angular.dev/cdk/categories" target="_blank" rel="noreferrer">Component Dev Kit (CDK)</a> is a set of behavior primitives for building components. To use the component harnesses, first install <code>@angular/cdk</code> from npm. You can do this from your terminal using the Angular CLI:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cdk</span></span></code></pre></div><h2 id="creating-a-testelement-implementation" tabindex="-1">Creating a <code>TestElement</code> implementation <a class="header-anchor" href="#creating-a-testelement-implementation" aria-label="Permalink to &quot;Creating a `TestElement` implementation&quot;">​</a></h2><p>Every test environment must define a <code>TestElement</code> implementation. The <code>TestElement</code> interface serves as an environment-agnostic representation of a DOM element. It enables harnesses to interact with DOM elements regardless of the underlying environment. Because some environments don&#39;t support interacting with DOM elements synchronously (e.g. WebDriver), all <code>TestElement</code> methods are asynchronous, returning a <code>Promise</code> with the result of the operation.</p><p><code>TestElement</code> offers a number of methods to interact with the underlying DOM such as <code>blur()</code>, <code>click()</code>, <code>getAttribute()</code>, and more. See the <a href="https://angular.dev/api/cdk/testing/TestElement" target="_blank" rel="noreferrer">TestElement API reference page</a> for the full list of methods.</p><p>The <code>TestElement</code> interface consists largely of methods that resemble methods available on <code>HTMLElement</code>. Similar methods exist in most test environments, which makes implementing the methods fairly straightforward. However, one important difference to note when implementing the <code>sendKeys</code> method, is that the key codes in the <code>TestKey</code> enum likely differ from the key codes used in the test environment. Environment authors should maintain a mapping from <code>TestKey</code> codes to the codes used in the particular testing environment.</p><p>The <a href="https://angular.dev/api/cdk/testing/testbed/UnitTestElement" target="_blank" rel="noreferrer">UnitTestElement</a> and <a href="https://angular.dev/api/cdk/testing/selenium-webdriver/SeleniumWebDriverElement" target="_blank" rel="noreferrer">SeleniumWebDriverElement</a> implementations in Angular CDK serve as good examples of implementations of this interface.</p><h2 id="creating-a-harnessenvironment-implementation" tabindex="-1">Creating a <code>HarnessEnvironment</code> implementation <a class="header-anchor" href="#creating-a-harnessenvironment-implementation" aria-label="Permalink to &quot;Creating a `HarnessEnvironment` implementation&quot;">​</a></h2><p>Test authors use <code>HarnessEnvironment</code> to create component harness instances for use in tests. <code>HarnessEnvironment</code> is an abstract class that must be extended to create a concrete subclass for the new environment. When supporting a new test environment, create a <code>HarnessEnvironment</code> subclass that adds concrete implementations for all abstract members.</p><p><code>HarnessEnvironment</code> has a generic type parameter: <code>HarnessEnvironment&lt;E&gt;</code>. This parameter, <code>E</code>, represents the raw element type of the environment. For example, this parameter is Element for unit test environments.</p><p>The following are the abstract methods that must be implemented:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>abstract getDocumentRoot(): E</code></td><td style="text-align:left;">Gets the root element for the environment (e.g. <code>document.body</code>).</td></tr><tr><td style="text-align:left;"><code>abstract createTestElement(element: E): TestElement</code></td><td style="text-align:left;">Creates a <code>TestElement</code> for the given raw element.</td></tr><tr><td style="text-align:left;"><code>abstract createEnvironment(element: E): HarnessEnvironment</code></td><td style="text-align:left;">Creates a <code>HarnessEnvironment</code> rooted at the given raw element.</td></tr><tr><td style="text-align:left;"><code>abstract getAllRawElements(selector: string): Promise&lt;E[]&gt;</code></td><td style="text-align:left;">Gets all of the raw elements under the root element of the environment matching the given selector.</td></tr><tr><td style="text-align:left;"><code>abstract forceStabilize(): Promise&lt;void&gt;</code></td><td style="text-align:left;">Gets a <code>Promise</code> that resolves when the <code>NgZone</code> is stable. Additionally, if applicable, tells <code>NgZone</code> to stabilize (e.g. calling <code>flush()</code> in a <code>fakeAsync</code> test).</td></tr><tr><td style="text-align:left;"><code>abstract waitForTasksOutsideAngular(): Promise&lt;void&gt;</code></td><td style="text-align:left;">Gets a <code>Promise</code> that resolves when the parent zone of <code>NgZone</code> is stable.</td></tr></tbody></table><p>In addition to implementing the missing methods, this class should provide a way for test authors to get <code>ComponentHarness</code> instances. You should define a protected constructor and provide a static method called <code>loader</code> that returns a <code>HarnessLoader</code> instance. This allows test authors to write code like: <code>SomeHarnessEnvironment.loader().getHarness(...)</code>. Depending on the needs of the particular environment, the class may provide several different static methods or require arguments to be passed. (e.g. the <code>loader</code> method on <code>TestbedHarnessEnvironment</code> takes a <code>ComponentFixture</code>, and the class provides additional static methods called <code>documentRootLoader</code> and <code>harnessForFixture</code>).</p><p>The <a href="https://angular.dev/api/cdk/testing/testbed/TestbedHarnessEnvironment" target="_blank" rel="noreferrer"><code>TestbedHarnessEnvironment</code></a> and <a href="https://angular.dev/api/cdk/testing/selenium-webdriver/SeleniumWebDriverHarnessEnvironment" target="_blank" rel="noreferrer">SeleniumWebDriverHarnessEnvironment</a> implementations in Angular CDK serve as good examples of implementations of this interface.</p><h2 id="handling-auto-change-detection" tabindex="-1">Handling auto change detection <a class="header-anchor" href="#handling-auto-change-detection" aria-label="Permalink to &quot;Handling auto change detection&quot;">​</a></h2><p>In order to support the <code>manualChangeDetection</code> and parallel APIs, your environment should install a handler for the auto change detection status.</p><p>When your environment wants to start handling the auto change detection status it can call <code>handleAutoChangeDetectionStatus(handler)</code>. The handler function will receive a <code>AutoChangeDetectionStatus</code> which has two properties <code>isDisabled</code> and <code>onDetectChangesNow()</code>. See the <a href="https://angular.dev/api/cdk/testing/AutoChangeDetectionStatus" target="_blank" rel="noreferrer">AutoChangeDetectionStatus API reference page</a> for more information. If your environment wants to stop handling auto change detection status it can call <code>stopHandlingAutoChangeDetectionStatus()</code>.</p>',26)]))}const g=t(s,[["render",r]]);export{p as __pageData,g as default};
